import {COLORS,MAX_SECONDS,MAX_FILE_BYTES,uid,clone,fmt,esc,clamp,createProject,demoVersion,sectionsFor,makeSnapshot,versionDirty,interpretRequest,applyProposal,assertTrim,logEvent,evaluateStudy,emptyStudy,validateStudyRecord,toCSV} from './core.mjs';
import * as storage from './storage.mjs';
import {Player} from './player.mjs';
import {createUI} from './ui.mjs';
import {createGenerations} from './generations.mjs';
import {createEvaluations} from './evaluations.mjs';
import {lyricsState,LYRICS_STATUS} from './generation-core.mjs';
const $=s=>document.querySelector(s),app=$('#app'),dialog=$('#dialog');
const state={project:null,projects:[],records:[],page:'studio',tab:'lyrics',section:'chorus',editingLyrics:false,proposal:null,ab:'B',peaks:[],audioBusy:false,storageError:false,saveText:'正在打开本机项目…'};
let saveTimer,saveRevision=0,saveChain=Promise.resolve(),toastTimer,waveToken=0;
const player=new Player(updateTransport);
const ui=createUI(state,player,getVersion);
const generation=createGenerations({state,player,storage,modal,closeModal,save,flush,render,stopForChange,preserveDraft,toast,download});
const evaluation=createEvaluations({state,storage,player,modal,closeModal,save,flush,render,stopForChange,preserveDraft,toast,download});
async function flush(){await saveChain;if(state.storageError)throw new Error('本机保存未完成，请重试保存或导出重要内容。');}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5200);}
function status(text){state.saveText=text;if($('#save-state'))$('#save-state').textContent=text;}
function save(){if(!state.project)return;state.project.updatedAt=new Date().toISOString();status('正在保存到本机…');const revision=++saveRevision,value=clone(state.project);saveChain=saveChain.then(()=>storage.put('projects',value)).then(()=>{const i=state.projects.findIndex(p=>p.id===value.id);if(i<0)state.projects.push(value);else state.projects[i]=value;if(revision===saveRevision){state.storageError=false;status('已保存到此浏览器');}}).catch(e=>{state.storageError=true;status('未能保存 · 请导出重要音频');toast(e.message);});}
function invalidateAudio(){player.pause();state.proposal=null;state.ab='B';state.peaks=[];waveToken++;}
function stopForChange(){invalidateAudio();player.offset=state.project.working?.trim.start||0;}
function getVersion(){const p=state.project;return !p?null:state.ab==='A'?(p.versions.find(v=>v.id===p.compareId)||p.versions[0]):p.working;}
function selectedSection(){const v=state.project.working;return v?.sections.find(s=>s.id===state.section)||v?.sections[0];}
function render(){const v=state.project.working;if(v&&!v.sections.some(s=>s.id===state.section))state.section=v.sections[0]?.id||'chorus';app.innerHTML=ui.shell();updateTransport();if(state.page==='studio')refreshWave();}
async function refreshWave(){const v=getVersion();if(!v)return;const token=++waveToken;try{const {peaks,mix}=await player.render(v);if(token!==waveToken)return;state.peaks=peaks;state.clippedSamples=mix.clippedSamples||0;if($('#peak-warning'))$('#peak-warning').textContent=state.clippedSamples?'当前试听有过载，请降低音轨音量后导出。':'';const frame=$('#waveform');if(frame){frame.innerHTML=ui.waveHTML()+'<span class="playhead" id="playhead"></span>';updateTransport();}}catch(error){if(token===waveToken)toast(error.message);}}
function updateTransport(){if(!state.project)return;const v=getVersion(),pos=player.position||v?.trim.start||0;const play=$('#play-btn');if(play){play.innerHTML=ui.icon(player.playing?'pause':'play');play.setAttribute('aria-label',player.playing?'暂停':'播放');play.disabled=!v||state.audioBusy;}const seek=$('#seek');if(seek){seek.max=v?.duration||1;if(document.activeElement!==seek)seek.value=pos;}if($('#current-time'))$('#current-time').textContent=fmt(pos);if($('#total-time'))$('#total-time').textContent=fmt(v?.duration||0);if($('#playing-label'))$('#playing-label').textContent=state.audioBusy?'正在准备音频…':`${state.ab==='A'?'A · 基准版本':'B · 当前修改'}${v?.source==='demo'?' · 器乐':''}`;if($('#playhead'))$('#playhead').style.left=`${clamp(pos/(v?.duration||1)*100,0,100)}%`;if($('#waveform'))$('#waveform').setAttribute('aria-valuenow',pos.toFixed(1));}
function tick(){if(player.playing)updateTransport();requestAnimationFrame(tick);}requestAnimationFrame(tick);
async function playCurrent(position){const v=getVersion();if(!v)return;state.audioBusy=true;updateTransport();try{await player.play(clone(v),position);logEvent(state.project,'listen',{versionId:v.id,comparison:state.ab});save();}catch(e){toast(e.message);}finally{state.audioBusy=false;updateTransport();}}
async function seekTo(value){const v=getVersion();if(!v)return;const position=clamp(value,v.trim.start,v.trim.end),wasPlaying=player.playing;player.pause();player.offset=position;updateTransport();if(wasPlaying)await playCurrent(position);}
async function switchAB(value){if(!['A','B'].includes(value)||!state.project.working)return;const position=player.position,wasPlaying=player.playing;player.pause();state.ab=value;const v=getVersion();player.offset=clamp(position,v.trim.start,v.trim.end);logEvent(state.project,'ab_compare',{side:value,versionId:v.id});save();render();if(wasPlaying)await playCurrent(player.offset);}
function preserveDraft(){if(versionDirty(state.project))makeSnapshot(state.project,'暂存的调整','切换前自动保留的音轨与歌词调整。');}
function modal(title,body){player.pause();$('#dialog-content').innerHTML=`<div class="dialog-header"><h2>${esc(title)}</h2><button class="icon-btn" data-act="close-dialog" aria-label="关闭对话框">${ui.icon('close')}</button></div>${body}`;if(!dialog.open)dialog.showModal();}
function closeModal(){dialog.close();$('#dialog-content').innerHTML='';}
function formError(e){if($('#form-error'))$('#form-error').textContent=e.message;else toast(e.message);}
const errHTML='<div class="form-error" id="form-error" role="alert"></div>';
function projectModal(isNew=false){const p=state.project;modal(isNew?'从一个想法开始':'作品与创作想法',`<form id="project-form" data-new="${isNew}"><div class="dialog-body"><label>作品名称<input name="title" required maxlength="80" placeholder="给这首歌一个名字" value="${isNew?'':esc(p.title)}"></label><label>创作语言<select name="language"><option value="zh" ${!isNew&&p.language==='zh'?'selected':''}>中文</option><option value="en" ${!isNew&&p.language==='en'?'selected':''}>English</option></select></label><label>想表达的故事、情绪或声音<textarea name="brief" rows="3" maxlength="3000" placeholder="例如：写给离开家乡的自己，温暖、坚定，有一点怀念。">${isNew?'':esc(p.brief)}</textarea></label>${isNew?'<label>已有歌词（可选）<textarea name="lyrics" rows="4" maxlength="12000" placeholder="可以先贴几句，之后继续编辑…"></textarea></label>':''}<div class="notice">歌词和想法会保存在本机项目中。可在生成入口准备歌词与声音方向，连接服务后生成真实演唱。</div>${errHTML}</div><div class="dialog-footer"><button type="button" class="btn quiet" data-act="close-dialog">取消</button><button class="btn primary" type="submit">${isNew?'创建作品':'保存想法'}</button></div></form>`);}
function directionsModal(){modal('先听听，两种不同的感觉',`<div class="dialog-body"><p>这是两段原创器乐方向示例，可用来讨论编曲感受。它们是预制演示，不会按你的歌词或想法自动生成。</p><div class="direction-grid">${[['warm','piano','晚风里的电钢琴','88 BPM · C major','柔和的琴键、疏朗的节奏，留出讲故事的空间。'],['bright','music','往前走的轻快节奏','108 BPM · C major','明亮拨弦和更清晰的节拍，带一点向前的力量。']].map(([id,ico,name,meta,description])=>`<div class="direction-card"><div class="direction-icon">${ui.icon(ico)}</div><h3>${name}</h3><span class="small muted">${meta}</span><p style="margin-top:12px">${description}</p><button class="btn" data-act="preview-direction" data-direction="${id}">${ui.icon('play')}试听 15 秒</button><button class="btn primary" data-act="choose-direction" data-direction="${id}">用这个器乐方向</button></div>`).join('')}</div><p class="small">选中后保留已有歌词，并加入完整结构的器乐。已有音频版本也会保留。</p></div>`);}
function importModal(stem=false){const v=state.project.working;if(stem&&!v)return;modal(stem?'加入一条独立音轨':'导入你的音乐',`<form id="import-form" data-stem="${stem}"><div class="dialog-body"><p>${stem?'把已经分离或单独录制的音轨加入当前版本。所有音轨从 00:00 对齐，短轨补静音，超出作品时长的部分不播放。':'导入自己的小样或外部制作结果。它会成为一个新版本，已有作品会保留。'}</p><div class="upload-zone">${ui.icon('upload')}<h3>${stem?'选择独立音轨':'把灵感带进创作室'}</h3><p>WAV、MP3、M4A、OGG · 最大 30 MB · 最长 5 分钟</p><input name="audio" type="file" accept="audio/*,.wav,.mp3,.m4a,.ogg,.flac" required aria-label="选择音频文件"></div><label>${stem?'音轨名称':'版本名称'}<input name="name" maxlength="60" placeholder="${stem?'例如：主唱人声':'例如：我的第一版小样'}"></label>${stem?`<label>音轨类型<select name="kind"><option value="vocals">人声</option><option value="harmony">伴奏 / 和声</option><option value="drums">鼓组</option><option value="bass">贝斯</option><option value="melody">主旋律</option><option value="mix">其他混合音频</option></select></label>${v.tracks.some(t=>t.kind==='mix')?'<label class="check"><input type="checkbox" name="muteMix" checked>静音原混合音轨，避免重复播放</label>':''}`:'<div class="notice">导入后是单条混合音轨，不会自动分轨。已有歌词将保留；段落时间会按新时长重建，需试听核对。</div>'}${errHTML}</div><div class="dialog-footer"><button class="btn quiet" type="button" data-act="close-dialog">取消</button><button id="import-submit" class="btn primary" type="submit">导入并保留原版</button></div></form>`);}
function saveVersionModal(){modal('留下这个版本',`<form id="version-form"><div class="dialog-body"><label>版本名称<input name="name" maxlength="60" required value="创作版本 ${state.project.versions.length+1}"></label><label>这次喜欢的变化<textarea name="notes" maxlength="1000" rows="3" placeholder="为什么留下这一版…"></textarea></label>${errHTML}</div><div class="dialog-footer"><button class="btn primary">保存版本</button></div></form>`);}
function exportModal(){const p=state.project,v=p.working;if(!v)return;modal('把这首歌带走',`<div class="dialog-body"><div class="flex between"><h3>${esc(p.title)}</h3><span class="badge">${fmt(v.trim.end-v.trim.start)}</span></div><p>导出当前 B 版本，包含音轨音量、静音、局部修改与裁剪。播放器的监听音量不会改变导出文件。</p><button class="btn primary" data-act="generation-save-wav">保存 WAV 到本机文件夹</button><button class="btn" data-act="download-wav">${ui.icon('download')}下载 WAV 音频</button><button class="btn" data-act="download-lyrics">${ui.icon('file')}下载歌词与创作信息</button><button class="btn quiet" data-act="request">导出后续制作需求单</button>${v.tracks.some(t=>t.assetId)?'<button class="btn" data-act="generation-save-original">保存原始音频到本机文件夹</button><button class="btn quiet" data-act="download-original">下载原始音频文件</button>':''}<div class="notice">${v.source==='demo'?'当前音频为原创器乐演示，不含歌词演唱。 ':''}编辑版 WAV：${(v.sampleRate||22050)/1000} kHz / 24 bit / 立体声。新增导入完整保留原始文件；更高的格式参数不代表恢复原本缺失的音质。</div>${errHTML}</div>`);}
const downloadUrls=[];
window.addEventListener('pagehide',()=>downloadUrls.forEach(url=>URL.revokeObjectURL(url)));
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');downloadUrls.push(url);if(downloadUrls.length>4)URL.revokeObjectURL(downloadUrls.shift());a.href=url;a.download=name.replace(/[<>:"/\\|?*\x00-\x1f]/g,'_');a.textContent=`保存文件：${a.download}`;a.className='btn primary';const old=$('#download-result');if(old)old.remove();const result=document.createElement('div');result.id='download-result';result.className='dialog-body';result.append(a);if(dialog.open)$('#dialog-content').append(result);else{modal('文件已准备好','<div class="dialog-body"><p>点击下方文件保存到你的设备。</p></div>');$('#dialog-content').append(result);}a.click();}
function lyricsText(){const p=state.project;return `${p.title}\n创作语言：${p.language==='zh'?'中文':'English'}\n创作想法：${p.brief}\n\n${p.working?.sections.map(s=>`[${s.name}] ${fmt(s.start)}–${fmt(s.end)}\n${s.lyrics}`).join('\n\n')||p.seedLyrics||''}\n\n说明：${LYRICS_STATUS[lyricsState(p.working)]}\n`;}
function requestModal(){const p=state.project,recent=p.messages.filter(m=>m.role==='user').at(-1)?.text||'请依据创作想法和歌词制作完整歌曲。';const content=`制作需求单｜${p.title}\n\n${lyricsText()}\n本次修改意图：${recent}\n参考版本：${p.working?.name||'尚无音频'}\n处理区间：${selectedSection()?`${selectedSection().name} ${fmt(selectedSection().start)}–${fmt(selectedSection().end)}`:'待确定'}\n\n请先与创作者确认：需要保留的人声/旋律/伴奏、允许变化的范围、处理费用与预期质量。\n交付：完整试听音频；如涉及分轨控制，请同时提供从 00:00 对齐的独立音轨。\n由创作者试听确认后，再导入声间作为新版本。\n\n可通过工作台的生成入口提交全新歌曲；自动分轨尚未接入。此需求单不会自动发送给任何人。`;modal('后续制作需求单',`<div class="dialog-body"><p>用于外部工具或人工制作。导出后由你自行交付；本工作台不会发送或产生处理费用。</p><div class="request-preview">${esc(content)}</div><button class="btn primary" data-act="download-request">下载需求单</button></div>`);state.requestText=content;}
function trimModal(){const v=state.project.working;modal('选择保留的音频范围',`<form id="trim-form"><div class="dialog-body"><p>原始音频保留。范围用于当前版本的播放与 WAV 导出，最少保留 0.5 秒。</p><div class="form-grid"><label>开始时间（秒）<input name="start" type="number" min="0" max="${v.duration}" step="0.01" value="${v.trim.start.toFixed(2)}" required></label><label>结束时间（秒）<input name="end" type="number" min="0.5" max="${v.duration+.01}" step="0.01" value="${v.trim.end.toFixed(2)}" required></label></div>${errHTML}</div><div class="dialog-footer"><button type="button" class="btn quiet" data-act="reset-trim">恢复完整长度</button><button class="btn primary">应用范围</button></div></form>`);}
function sectionTimeModal(){const s=selectedSection(),v=state.project.working;if(!s)return;modal(`调整${s.name}的位置`,`<form id="section-form"><div class="dialog-body"><p>段落标记用于定位试听和局部修改范围，不会移动或拉伸实际音频。</p><div class="form-grid"><label>开始时间（秒）<input name="start" type="number" required step="0.01" min="0" max="${v.duration}" value="${s.start.toFixed(2)}"></label><label>结束时间（秒）<input name="end" type="number" required step="0.01" min="0" max="${v.duration+.01}" value="${s.end.toFixed(2)}"></label></div>${errHTML}</div><div class="dialog-footer"><button class="btn primary">保存段落位置</button></div></form>`);}
function recordModal(id){const r=state.records.find(r=>r.id===id);if(!r)return;const checked=k=>r[k]?'checked':'';modal(`验证记录 · ${id}`,`<form id="study-form" data-record="${id}"><div class="dialog-body"><label class="check"><input type="checkbox" name="completed" ${checked('completed')}>已完成首次创作测试</label><div class="form-grid"><label>首次测试日期<input type="date" name="sessionDate" value="${r.sessionDate}"></label><label>实际回访日期<input type="date" name="returnDate" value="${r.returnDate}"></label></div>${[['shareReady','完成了一首愿意分享的完整歌曲'],['improved','修改改善了具体不满意的地方'],['preserved','重要的原有内容得到保留'],['voluntaryReturn','回访是参与者自愿发起']].map(([k,label])=>`<label class="check"><input type="checkbox" name="${k}" ${checked(k)}>${label}</label>`).join('')}<div class="form-grid">${[['modifications','完成修改次数'],['attempts','总尝试次数'],['minutes','完成用时（分钟）'],['cost','实际处理费用（人民币）'],['helpCount','人工帮助次数']].map(([key,label])=>`<label>${label}<input type="number" name="${key}" min="0" step="${key==='cost'?'.01':'1'}" required value="${r[key]}"></label>`).join('')}${[['pronunciation','发音质量'],['phrasing','断句质量']].map(([key,label])=>`<label>${label}<select name="${key}"><option value="">未评估 / 无演唱</option>${[1,2,3,4,5].map(n=>`<option ${String(r[key])===String(n)?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}</div><label>观察、人工参与、遇到的问题<textarea name="notes" rows="4" maxlength="5000" placeholder="记录实际发生的事情；留意修改是否只是变得更响。">${esc(r.notes)}</textarea></label><p>质量评分 1 为较差，5 为满意。未测试内容保留“未评估”。</p>${errHTML}</div><div class="dialog-footer"><button class="btn primary">保存验证记录</button></div></form>`);}

async function sendMessage(text){text=text.trim();if(!text)return;if(text.length>2000)throw new Error('请把修改想法控制在 2000 字以内。');const p=state.project;p.messages.push({role:'user',text});if(p.messages.length>100)p.messages.splice(0,p.messages.length-100);let target=state.section;if(/副歌|chorus/i.test(text))target='chorus';state.proposal={...interpretRequest(text,p.working,target),basis:p.working?JSON.stringify(p.working):''};if(state.proposal.kind==='brief'){p.brief=text;p.stage=2;}p.messages.push({role:'assistant',text:state.proposal.explanation});logEvent(p,'modification_requested',{kind:state.proposal.kind});save();render();$('#conversation')?.scrollTo(0,100000);}
async function handleAction(el){const action=el.dataset.act,p=state.project;
  if(action.startsWith('evaluation-'))return evaluation.action(el);
  if(action.startsWith('generation-')||action==='download-original')return generation.action(el);
  if(action==='page'){state.page=el.dataset.page;render();window.scrollTo(0,0);}
  else if(action==='new-project')projectModal(true);
  else if(action==='edit-project')projectModal();
  else if(action==='close-dialog')closeModal();
  else if(action==='projects'){await saveChain;const projects=await storage.all('projects');modal('我的创作',`<div class="dialog-body project-list">${projects.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).map(x=>`<button class="project-item" data-act="open-project" data-project="${x.id}"><div><h3>${esc(x.title)}</h3><span>${x.versions.length} 个版本 · ${x.language==='en'?'English':'中文'}</span></div>${ui.icon('chevron')}</button>`).join('')}</div>`);}
  else if(action==='open-project'){await saveChain;const next=await storage.get('projects',el.dataset.project);if(!next)throw new Error('找不到这个项目。');stopForChange();state.project=next;state.page='studio';state.tab='lyrics';state.editingLyrics=false;await storage.put('meta',{id:'last-project',value:next.id});closeModal();render();}
  else if(action==='tab'){state.tab=el.dataset.tab;render();}
  else if(action==='step'){const n=Number(el.dataset.step);if(n===1)projectModal();else if(n===2)directionsModal();else if(n===3)await generation.action({dataset:{act:'generation-open'}});else if(n===4){state.page='studio';render();$('#chat-input')?.focus();}else exportModal();}
  else if(action==='suggest')await sendMessage(el.dataset.text);
  else if(action==='dismiss-proposal'){state.proposal=null;render();}
  else if(action==='apply-proposal'){if(!state.proposal||state.proposal.basis!==JSON.stringify(p.working))throw new Error('作品已发生变化，请重新描述这次修改。');player.pause();preserveDraft();applyProposal(p,state.proposal);p.messages.push({role:'assistant',text:'修改已保存为新版本。用底部 A / B 比较，听听这个变化是否更接近你的想法。'});state.proposal=null;state.ab='B';save();render();toast('新版本已保留，可切换 A / B 试听。');}
  else if(action==='directions')directionsModal();
  else if(action==='preview-direction'){const v=demoVersion(el.dataset.direction,p.language);v.trim={start:v.sections[3].start,end:v.sections[3].start+15};state.audioBusy=true;updateTransport();try{await player.play(v,v.trim.start);toast('正在试听 15 秒原创器乐示例。');}finally{state.audioBusy=false;updateTransport();}}
  else if(action==='choose-direction'){player.pause();preserveDraft();const v=demoVersion(el.dataset.direction,p.language);if(p.working){for(const s of v.sections)s.lyrics=p.working.sections.find(x=>x.id===s.id)?.lyrics||'';}else if(p.seedLyrics){for(const s of v.sections)s.lyrics=s.id==='verse'?p.seedLyrics:'';}else{for(const s of v.sections)s.lyrics='';}v.name=el.dataset.direction==='warm'?'温暖电钢琴方向':'明亮轻快方向';p.working=v;p.versions.push(clone(v));p.compareId=p.compareId||v.id;p.stage=3;logEvent(p,'direction_selected',{direction:v.direction});stopForChange();save();closeModal();render();toast('器乐方向已加入；歌词草稿已保留。');}
  else if(action==='import')importModal();
  else if(action==='add-stem'){if(p.working.tracks.length>=6)throw new Error('每个版本最多支持 6 条音轨。');importModal(true);}
  else if(action==='edit-lyrics'){if(state.editingLyrics){logEvent(p,'lyrics_edited');save();}state.editingLyrics=!state.editingLyrics;render();}
  else if(action==='section'){if(state.ab==='A'){player.pause();state.ab='B';}state.section=el.dataset.section;const s=selectedSection();render();if(s)await seekTo(s.start);}
  else if(action==='section-time')sectionTimeModal();
  else if(action==='save-version')saveVersionModal();
  else if(action==='load-version'){const v=p.versions.find(v=>v.id===el.dataset.version);if(!v)throw new Error('找不到这个版本。');stopForChange();preserveDraft();p.working=clone(v);logEvent(p,'version_restored',{versionId:v.id});player.offset=v.trim.start;save();render();toast('已恢复此版本；其他版本仍在记录中。');}
  else if(action==='compare-version'){p.compareId=el.dataset.version;save();await switchAB('A');toast('已设为 A 基准版本。');}
  else if(action==='ab')await switchAB(el.dataset.ab);
  else if(action==='play'){if(player.playing)player.pause();else await playCurrent();}
  else if(action==='restart')await seekTo(getVersion()?.trim.start||0);
  else if(action==='mute'||action==='solo'){const t=p.working.tracks.find(t=>t.id===el.dataset.track);if(!t)return;invalidateAudio();t[action==='mute'?'muted':'solo']=!t[action==='mute'?'muted':'solo'];save();render();}
  else if(action==='clear-effects'){invalidateAudio();p.working.effects=[];save();render();toast('已移除当前草稿的局部调整；保存版本未变。');}
  else if(action==='trim')trimModal();
  else if(action==='reset-trim'){invalidateAudio();p.working.trim={start:0,end:p.working.duration};save();closeModal();render();}
  else if(action==='export')exportModal();
  else if(action==='download-wav'){const old=el.innerHTML;el.disabled=true;el.textContent='正在制作音频文件…';try{const wav=await player.wav(clone(p.working));download(wav,`${p.title}-${p.working.name}.wav`);p.stage=5;logEvent(p,'wav_export_prepared',{versionId:p.working.id});save();toast('音频文件已生成；若未自动下载，请点击保存文件链接。');}finally{el.disabled=false;el.innerHTML=old;}}
  else if(action==='download-lyrics'){download(new Blob([lyricsText()],{type:'text/plain;charset=utf-8'}),`${p.title}-歌词.txt`);toast('歌词文件已准备好。');}
  else if(action==='request')requestModal();
  else if(action==='download-request'){download(new Blob([state.requestText],{type:'text/plain;charset=utf-8'}),`${p.title}-制作需求单.txt`);toast('制作需求单已下载。');}
  else if(action==='study-record')recordModal(el.dataset.record);
  else if(action==='export-study'){const keys=['id','language','completed','sessionDate','returnDate','voluntaryReturn','shareReady','improved','preserved','modifications','attempts','minutes','cost','helpCount','pronunciation','phrasing','notes'];const labels=['参与者','语言','已完成','首次测试','实际回访','自愿回访','愿意分享','修改改善','保留重要内容','修改次数','尝试次数','用时分钟','费用人民币','人工帮助次数','发音质量','断句质量','观察'];download(new Blob([toCSV([labels,...state.records.map(r=>keys.map(k=>r[k]))])],{type:'text/csv;charset=utf-8'}),'声间-首轮验证记录.csv');}
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-act]');if(!el||el.disabled)return;event.preventDefault();Promise.resolve(handleAction(el)).catch(formError);});
document.addEventListener('click',event=>{const w=event.target.closest('#waveform');if(w){const r=w.getBoundingClientRect();seekTo((event.clientX-r.left)/r.width*(getVersion()?.duration||0)).catch(formError);}});
document.addEventListener('input',event=>{const el=event.target,p=state.project;if(el.matches('[data-seed-lyrics]')){p.seedLyrics=el.value;save();}if(el.matches('[data-lyric]')){p.working.sections.find(s=>s.id===el.dataset.lyric).lyrics=el.value;state.proposal=null;save();}if(el.matches('[data-gain]')){invalidateAudio();const t=p.working.tracks.find(t=>t.id===el.dataset.gain);t.gain=Number(el.value)/100;$(`#gain-${t.id}`).textContent=`${el.value}%`;save();}if(el.id==='volume')player.setVolume(Number(el.value)/100);});
document.addEventListener('change',event=>{if(event.target.id==='seek')seekTo(Number(event.target.value)).catch(formError);if(event.target.matches('[data-gain]'))refreshWave();});
document.addEventListener('keydown',event=>{const el=event.target;if(el.id==='chat-input'&&event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();$('#chat-form').requestSubmit();}if(el.id==='waveform'&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();seekTo(player.position+(event.key==='ArrowRight'?5:-5)).catch(formError);}if(event.code==='Space'&&!dialog.open&&!el.closest('input,textarea,select,button,[contenteditable]')){event.preventDefault();if(player.playing)player.pause();else playCurrent();}});
dialog.addEventListener('close',()=>{player.pause();if(state.project)render();});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
document.addEventListener('submit',event=>{event.preventDefault();submitForm(event.target).catch(formError);});
async function submitForm(form){const data=new FormData(form),p=state.project;
  if(form.id==='evaluation-form')return evaluation.submit(form);
  if(form.id==='generation-form')return generation.submit();
  if(form.id==='chat-form')await sendMessage($('#chat-input').value);
  else if(form.id==='project-form'){const values={title:String(data.get('title')).trim(),brief:String(data.get('brief')).trim(),language:data.get('language')};if(!values.title)throw new Error('请填写作品名称。');if(form.dataset.new==='true'){stopForChange();const project=createProject({...values,demo:false});project.seedLyrics=String(data.get('lyrics')||'').trim();await storage.put('projects',project);state.project=project;state.projects.push(clone(project));await storage.put('meta',{id:'last-project',value:project.id});state.page='studio';state.editingLyrics=false;state.tab='lyrics';}else Object.assign(p,values);save();closeModal();render();}
  else if(form.id==='version-form'){makeSnapshot(p,String(data.get('name')),String(data.get('notes'))||'手动保留的创作版本。');save();closeModal();render();toast('这个版本已保留。');}
  else if(form.id==='trim-form'){const trim=assertTrim(Number(data.get('start')),Number(data.get('end')),p.working.duration);invalidateAudio();p.working.trim=trim;player.offset=trim.start;logEvent(p,'trim_changed',trim);save();closeModal();render();}
  else if(form.id==='section-form'){const section=selectedSection(),range=assertTrim(Number(data.get('start')),Number(data.get('end')),p.working.duration);invalidateAudio();Object.assign(section,range);save();closeModal();render();}
  else if(form.id==='study-form'){const existing=state.records.find(r=>r.id===form.dataset.record),record={...existing};for(const key of ['completed','shareReady','improved','preserved','voluntaryReturn'])record[key]=data.has(key);for(const key of ['modifications','attempts','minutes','cost','helpCount'])record[key]=Number(data.get(key));for(const key of ['sessionDate','returnDate','pronunciation','phrasing','notes'])record[key]=String(data.get(key)||'');validateStudyRecord(record);const records=state.records.map(r=>r.id===record.id?record:r);await storage.put('meta',{id:'study',value:records});state.records=records;closeModal();render();toast('验证记录已保存在本机。');}
  else if(form.id==='import-form'){const file=data.get('audio'),isStem=form.dataset.stem==='true';if(!(file instanceof File)||!file.size)throw new Error('请选择有效的音频文件。');if(file.size>MAX_FILE_BYTES)throw new Error('文件超过 30 MB，请先压缩或裁剪。');const btn=$('#import-submit');btn.disabled=true;btn.textContent='正在读取音频…';try{const decoded=await player.decode(file);if(!dialog.open||$('#import-form')!==form||state.project!==p)return;if(decoded.duration>MAX_SECONDS)throw new Error('音频超过 5 分钟，请先裁剪。');if(decoded.duration<.5)throw new Error('音频至少需要 0.5 秒。');const asset={id:uid(),name:file.name,...decoded};await storage.put('assets',asset);if(!dialog.open||$('#import-form')!==form||state.project!==p)return;stopForChange();preserveDraft();const name=String(data.get('name')||file.name.replace(/\.[^.]+$/,'')).trim();const track={id:uid(),assetId:asset.id,name:name||'导入音频',kind:isStem?data.get('kind'):'mix',gain:1,muted:false,solo:false,color:COLORS[isStem?p.working.tracks.length:0]};if(isStem){if(data.has('muteMix'))p.working.tracks.filter(t=>t.kind==='mix').forEach(t=>t.muted=true);p.working.tracks.push(track);p.working.sampleRate=Math.max(p.working.sampleRate||22050,asset.sampleRate);makeSnapshot(p,`加入${track.name}`,'导入独立音轨，从 00:00 对齐。');}else{const sections=sectionsFor(decoded.duration,p.language,false);for(const s of sections)s.lyrics=p.working?.sections.find(x=>x.id===s.id)?.lyrics||(s.id==='verse'?p.seedLyrics||'':'');const version={id:uid(),name:track.name,notes:`导入 ${file.name}，段落时间待核对。`,createdAt:new Date().toISOString(),source:'import',sampleRate:decoded.sampleRate,duration:decoded.duration,trim:{start:0,end:decoded.duration},sections,effects:[],tracks:[track]};p.working=version;p.versions.push(clone(version));p.compareId=p.compareId||version.id;p.stage=4;}logEvent(p,'audio_imported',{independentStem:isStem,duration:decoded.duration});save();closeModal();render();toast('音频已导入，已有版本已保留。');}finally{if(btn.isConnected){btn.disabled=false;btn.textContent='导入并保留原版';}}}
}
async function initialize(){try{state.projects=await storage.all('projects');const last=await storage.get('meta','last-project');state.project=state.projects.find(p=>p.id===last?.value)||state.projects.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];if(!state.project){state.project=createProject();await storage.put('projects',state.project);state.projects=[clone(state.project)];}state.records=(await storage.get('meta','study'))?.value||emptyStudy();await evaluation.load();status('已保存到此浏览器');}catch(error){state.project=createProject();state.records=emptyStudy();state.storageError=true;status('临时会话 · 本机保存不可用');toast(error.message);}render();registerTools();generation.start();}
function registerTools(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'read_music_project',title:'读取当前音乐项目',description:'Read the visible music project, versions and capabilities. Does not return audio or modify the project.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('Expected an empty object.');const p=state.project;return {title:p.title,language:p.language,brief:p.brief,selectedSection:state.section,versions:p.versions.map(v=>({id:v.id,name:v.name,source:v.source})),capabilities:['local_audio_mixing','version_comparison','lyrics_draft','lyrics_audio_provenance'],musicService:state.musicService||{configured:false},unavailable:['automatic_stem_separation','local_vocal_rewriting']};}},{name:'stage_music_edit',title:'准备音乐修改方案',description:'Stage a rule-based proposal in the visible conversation. Does not apply audio edits. User confirms supported edits in the UI.',inputSchema:{type:'object',properties:{request:{type:'string',minLength:1,maxLength:2000}},required:['request'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},async execute(input){if(!input||typeof input.request!=='string'||!input.request.trim()||input.request.length>2000||Object.keys(input).some(k=>k!=='request'))throw new Error('Expected a nonempty request up to 2000 characters.');state.page='studio';await sendMessage(input.request);return {kind:state.proposal.kind,title:state.proposal.title,applied:false};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
initialize();
